// Cria as tabelas que faltarem e insere os dados de demonstração (INSERT OR IGNORE: não duplica nem apaga)
msg.topic = `
CREATE TABLE IF NOT EXISTS usuarios (
  id          INTEGER PRIMARY KEY,
  telegram_id INTEGER UNIQUE,
  nome        TEXT NOT NULL,
  perfil      TEXT NOT NULL CHECK (perfil IN ('idoso', 'familiar')),
  idoso_id    INTEGER REFERENCES usuarios(id),   -- familiar: de qual idoso ele cuida
  parentesco  TEXT,
  ativo       INTEGER DEFAULT 1
);
CREATE TABLE IF NOT EXISTS unidades (
  id       INTEGER PRIMARY KEY,
  nome     TEXT NOT NULL,
  endereco TEXT,
  telefone TEXT
);
CREATE TABLE IF NOT EXISTS medicamentos (
  id       INTEGER PRIMARY KEY,
  idoso_id INTEGER NOT NULL REFERENCES usuarios(id),
  nome     TEXT NOT NULL,
  dose     TEXT,
  horario  TEXT NOT NULL,                         -- HH:MM
  ativo    INTEGER DEFAULT 1
);
CREATE TABLE IF NOT EXISTS doses (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  medicamento_id INTEGER NOT NULL REFERENCES medicamentos(id),
  data           TEXT NOT NULL,
  horario        TEXT NOT NULL,
  status         TEXT NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'confirmada', 'alertada')),
  enviado_em     TEXT,
  confirmado_em  TEXT,
  UNIQUE (medicamento_id, data, horario)
);
CREATE TABLE IF NOT EXISTS consultas (
  id            INTEGER PRIMARY KEY,
  idoso_id      INTEGER NOT NULL REFERENCES usuarios(id),
  unidade_id    INTEGER REFERENCES unidades(id),
  data          TEXT NOT NULL,
  hora          TEXT,
  especialidade TEXT
);
CREATE TABLE IF NOT EXISTS alertas (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  idoso_id  INTEGER NOT NULL REFERENCES usuarios(id),
  tipo      TEXT,
  mensagem  TEXT,
  criado_em TEXT DEFAULT (datetime('now', 'localtime'))
);
-- Quem foi avisado de cada alerta e quando (escalonamento: 1 linha por familiar avisado, ordem = ordem de cadastro)
CREATE TABLE IF NOT EXISTS alertas_envios (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  alerta_id   INTEGER NOT NULL REFERENCES alertas(id),
  idoso_id    INTEGER NOT NULL REFERENCES usuarios(id),
  familiar_id INTEGER NOT NULL REFERENCES usuarios(id),
  ordem       INTEGER NOT NULL,
  enviado_em  TEXT DEFAULT (datetime('now', 'localtime')),
  visto_em    TEXT,
  UNIQUE (alerta_id, familiar_id)
);
INSERT OR IGNORE INTO usuarios VALUES (1, 111111111, 'Dona Maria', 'idoso', NULL, NULL, 1);
INSERT OR IGNORE INTO usuarios VALUES (2, 222222222, 'Ana', 'familiar', 1, 'filha', 1);
INSERT OR IGNORE INTO unidades VALUES (1, 'UBS Vila Esperança', 'Rua das Flores, 120', '(11) 3000-0000');
INSERT OR IGNORE INTO medicamentos VALUES (1, 1, 'Losartana', '50 mg, 1 comprimido', '08:00', 1);
INSERT OR IGNORE INTO medicamentos VALUES (2, 1, 'Metformina', '850 mg, 1 comprimido', '12:30', 1);
INSERT OR IGNORE INTO medicamentos VALUES (3, 1, 'Sinvastatina', '20 mg, 1 comprimido', '20:00', 1);
INSERT OR IGNORE INTO consultas VALUES (1, 1, 1, date('now', 'localtime', '+3 days'), '09:30', 'Cardiologista');
`;
return msg;

// Entrada do Telegram (ou dos injects de teste): texto, mensagem de voz ou arquivo de áudio
const p = msg.payload || {};
const tipo = p.type;
if (!['message', 'voice', 'audio'].includes(tipo)) return null;   // fotos, figurinhas etc. são ignoradas
msg.canal = 'telegram';
msg.chatId = p.chatId;
msg.userId = (msg.originalMessage && msg.originalMessage.from) ? msg.originalMessage.from.id : p.chatId;
// Busca pelo ID do Telegram. Nos testes (sem Telegram) busca direto pelo id interno do usuário.
msg.params = (msg.teste && p.usuario) ? { $tg: -1, $uid: p.usuario } : { $tg: msg.userId, $uid: -1 };
if (tipo === 'message') {
    if (!p.content) return null;
    msg.pergunta = String(p.content).trim();
    msg.entradaVoz = false;
} else {
    msg.entradaVoz = true;
    msg.audioUrl = p.weblink;          // link temporário do Telegram (contém o token do bot: não exiba em debug)
    const a = msg.originalMessage && msg.originalMessage.audio;
    msg.audioNome = tipo === 'voice' ? 'voz.ogg' : ((a && a.file_name) || 'audio.mp3');
}
return msg;

// Saída 1 = usuário encontrado | Saída 2 = não cadastrado (responde com o ID para a família cadastrar)
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length === 0) {
    msg.resposta = 'Olá! Ainda não conheço você. Peça para sua família cadastrar este número no Acompanha: ' + msg.userId;
    node.status({ fill: 'red', shape: 'dot', text: 'não cadastrado: ' + msg.userId });
    return [null, msg];
}
msg.usuario = rows[0];
// O familiar conversa sobre o idoso de quem cuida; o idoso, sobre ele mesmo
msg.idosoId = msg.usuario.perfil === 'idoso' ? msg.usuario.id : msg.usuario.idoso_id;
node.status({ fill: 'green', shape: 'dot', text: msg.usuario.nome + ' (' + msg.usuario.perfil + ')' });
return [msg, null];

// Saída 1 = texto | Saída 2 = baixar o áudio do Telegram | Saída 3 = áudio já disponível (testes) | Saída 4 = erro
if (!msg.entradaVoz) return [msg, null, null, null];
if (Buffer.isBuffer(msg.audio)) return [null, null, msg, null];
if (msg.audioUrl) return [null, msg, null, null];
msg.resposta = 'Não recebi o áudio. Pode enviar de novo?';
return [null, null, null, msg];

// Prepara a consulta que traz tudo o que a IA precisa saber sobre o idoso
msg.params = { $idoso: msg.idosoId };
return msg;

// Monta o prompt do LLM: catálogo de intenções/entidades + dados do idoso + variável de contexto da conversa
const cat = flow.get('catalogo');
const linha = (Array.isArray(msg.payload) && msg.payload[0]) || {};
const lista = s => { try { return JSON.parse(s || '[]'); } catch (e) { return []; } };
msg.dados = {
    idoso: linha.idoso_nome || '',
    remedios: lista(linha.remedios),
    doses_hoje: lista(linha.doses_hoje),
    consultas: lista(linha.consultas),
    familiares: lista(linha.familiares),
    semana: lista(linha.semana)
};

// VARIÁVEL DE CONTEXTO: o que já aconteceu nesta conversa, guardado por chat_id
const contextos = flow.get('contextos') || {};
msg.contexto = contextos[msg.chatId] || { historico: [] };
const c = msg.contexto;

const fuso = env.get('FUSO') || 'America/Sao_Paulo';
const agora = new Date();
const quando = agora.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric', timeZone: fuso }) +
               ', ' + agora.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: fuso });

const intencoes = Object.entries(cat.intencoes).map(([nome, i]) =>
    '- ' + nome + ': ' + i.descricao + '. Exemplos: ' + i.exemplos.map(e => '"' + e + '"').join(', ')).join('\n');
const entidades = Object.entries(cat.entidades).map(([nome, e]) =>
    '- ' + nome + ': ' + e.descricao + '. Valores e sinônimos: ' +
    Object.entries(e.sinonimos).map(([v, s]) => v + (s.length ? ' (' + s.join(', ') + ')' : '')).join('; ')).join('\n');

msg.sistema = `Você é o Acompanha, um assistente por voz para idosos que moram sozinhos. Também conversa com os familiares que cuidam deles.
REGRAS DA RESPOSTA:
- Português do Brasil, frases curtas e simples, no máximo 3 frases. Tom carinhoso e calmo. Chame a pessoa pelo nome.
- A resposta será lida em voz alta: não use emojis, listas, markdown nem abreviações.
- Use SOMENTE os DADOS informados. Nunca invente remédio, dose, horário, data ou endereço. Se não souber, diga que vai pedir para a família verificar. Nunca diga que um remédio foi tomado se ele não aparecer como confirmada em DOSES DE HOJE: remédio de horário já passado e sem registro, diga que não há registro de que foi tomado.
- Nunca dê orientação médica (não mande tomar dose extra, trocar ou parar remédio).
- pedir_ajuda: diga que a família está sendo avisada agora e, se for grave, que ligue 192 (SAMU).
- falar_familiar: diga que vai mandar o recado para a família.
- confirmar_medicacao: se tomou, agradeça e diga que anotou (o sistema registra a dose). Descubra o remédio assim: (1) o que ela citou; (2) senão, o remédio com dose pendente em DOSES DE HOJE; (3) senão, o remédio cujo horário esteja entre 1 hora antes e 1 hora depois de DATA E HORA. Se achar, diga o nome dele e que anotou, sem perguntar nada. Só pergunte qual remédio ela tomou se nenhum desses se encaixar. Se ainda não tomou, diga que tudo bem e que vai lembrar de novo.
- Se quem fala é um familiar, responda sobre o idoso de quem ele cuida (pode usar o resumo da semana). O familiar já é da família: nunca diga que vai avisar a família. Sobre doses, diga só o que consta em DOSES DE HOJE: confirmada = já tomou; pendente ou alertada = ainda não tomou; sem registros = ainda não houve lembrete hoje.

CLASSIFIQUE a mensagem em UMA intenção:
${intencoes}
- outro: saudações, agradecimentos ou assuntos fora do escopo (responda com gentileza e diga em que pode ajudar).

EXTRAIA as entidades (use null quando não aparecerem):
${entidades}
No campo medicamento, use o nome do remédio cadastrado quando der para saber qual é.

Use o CONTEXTO DA CONVERSA para entender referências: "já tomei" sem dizer o remédio = o remédio que está aguardando confirmação ou o último citado.

Responda APENAS com um JSON válido, sem nenhum texto antes ou depois:
{"intencao": "...", "entidades": {"medicamento": null, "horario": null, "dia": null, "familiar": null, "unidade_saude": null}, "confirmou": null, "resposta": "..."}
"confirmou" só vale para confirmar_medicacao: true se disse que tomou, false se disse que ainda não tomou; nas outras intenções, null.`;

const d = msg.dados;
const fmt = (arr, f) => arr.length ? arr.map(f).join('; ') : '(sem registros)';
const quem = msg.usuario.perfil === 'idoso'
    ? msg.usuario.nome + ' (idoso)'
    : msg.usuario.nome + ' (familiar: ' + (msg.usuario.parentesco || 'cuidador') + ' de ' + d.idoso + ')';
msg.textoUsuario =
    'DATA E HORA: ' + quando + '\n' +
    'QUEM ESTÁ FALANDO: ' + quem + '\n\n' +
    'DADOS DE ' + d.idoso + ':\n' +
    'Remédios: ' + fmt(d.remedios, r => r.nome + ' ' + r.dose + ' às ' + r.horario) + '\n' +
    'Doses de hoje: ' + fmt(d.doses_hoje, x => x.remedio + ' das ' + x.horario + ' (' + x.status + ')') + '\n' +
    'Próximas consultas: ' + fmt(d.consultas, x => x.especialidade + ' em ' + x.data + ' às ' + x.hora + ', ' + x.unidade + ', ' + x.endereco + ', telefone ' + x.telefone) + '\n' +
    'Família: ' + fmt(d.familiares, f => f.nome + ' (' + f.parentesco + ')') + '\n' +
    'Semana (doses confirmadas/total por dia): ' + fmt(d.semana, s => s.data + ': ' + s.confirmadas + '/' + s.total) + '\n\n' +
    'CONTEXTO DA CONVERSA:\n' +
    'Última intenção: ' + (c.ultima_intencao || 'nenhuma') + '\n' +
    'Último remédio citado: ' + (c.ultimo_medicamento || 'nenhum') + '\n' +
    'Aguardando confirmação de: ' + (c.aguardando || 'nada') + '\n' +
    'Histórico recente:\n' + (c.historico.length ? c.historico.map(h => (h.quem === 'usuario' ? 'Pessoa: ' : 'Acompanha: ') + h.texto).join('\n') : '(início da conversa)') + '\n\n' +
    'MENSAGEM: ' + msg.pergunta;
return msg;

