        horario: { descricao: 'período ou hora do dia', sinonimos: { 'manhã': ['manha', 'de manhã', 'cedo', 'café da manhã'], 'meio-dia': ['meio dia', 'almoço', 'almoco'], 'tarde': ['de tarde', 'à tarde'], 'noite': ['de noite', 'à noite', 'antes de dormir', 'janta'], 'agora': ['agorinha', 'neste momento', 'já'] } },
        dia: { descricao: 'dia da semana ou dia relativo', sinonimos: { 'hoje': ['hj', 'neste dia'], 'amanhã': ['amanha'], 'depois de amanhã': ['depois de amanha'], 'esta semana': ['essa semana', 'nesta semana', 'nessa semana'] } },
        familiar: { descricao: 'pessoa da família ou cuidador', sinonimos: { 'filha': [], 'filho': [], 'neto': [], 'neta': [], 'nora': [], 'genro': [], 'cuidador': ['cuidadora', 'enfermeira', 'acompanhante'], 'família': ['familia', 'alguém', 'alguem', 'meus filhos'] } },
        unidade_saude: { descricao: 'local de atendimento', sinonimos: { 'unidade de saúde': ['posto', 'postinho', 'posto de saúde', 'ubs', 'clínica', 'clinica', 'ama', 'centro de saúde', 'hospital', 'médico', 'medico'] } }
