func:
// Pega o texto da IA. Se a Groq devolveu um erro (chave inválida, modelo, limite...), mostra o motivo no debug
const p = msg.payload || {};
const texto = p.choices && p.choices[0] && p.choices[0].message && p.choices[0].message.content;
if (texto) {
    node.status({ fill: 'green', shape: 'dot', text: 'ok' });
    msg.resposta = texto;
    return msg;
}
const fim = p.choices && p.choices[0] && p.choices[0].finish_reason;
if (fim === 'length') {
    node.warn('A IA gastou todos os tokens pensando e não escreveu a resposta → aumente "Max Tokens" no nó "Groq (G)" (ex.: 1500).');
}
const e = p.error || {};
const motivo = e.message || (msg.error && msg.error.message) || JSON.stringify(p).slice(0, 300);
const dicas = {
    invalid_api_key: 'A API Key está errada ou vazia: cole de novo no nó "Groq (G)", sem espaços.',
    model_not_found: 'Modelo inexistente ou desativado: use openai/gpt-oss-120b no nó "Groq (G)" (veja console.groq.com/docs/models).',
    model_decommissioned: 'Modelo desativado: use openai/gpt-oss-120b no nó "Groq (G)" (veja console.groq.com/docs/models).',
    rate_limit_exceeded: 'Limite gratuito atingido: espere um pouco e tente de novo.'
};
node.warn('A Groq recusou: ' + motivo + (e.code ? ' [' + e.code + ']' : '') + (dicas[e.code] ? ' → ' + dicas[e.code] : ''));
node.status({ fill: 'red', shape: 'ring', text: e.code || 'erro da Groq' });
msg.erroGroq = motivo;
msg.resposta = 'Tive um problema para consultar a IA agora. Tente novamente em instantes.';
return msg;

// Lê o JSON devolvido pelo LLM, valida a intenção e normaliza as entidades pelos sinônimos do catálogo
// Saída 1 = confirmar a dose no banco | Saída 2 = alertar a família | Saída 3 = segue para a resposta
const cat = flow.get('catalogo') || { intencoes: {}, entidades: {} };
if (msg.erroGroq) { msg.intencao = 'erro'; msg.entidades = {}; return [null, null, msg]; }

const bruto = String(msg.resposta || '');
let j = null;
const achou = bruto.match(/\{[\s\S]*\}/);
try { j = JSON.parse(achou ? achou[0] : bruto); } catch (e) { j = null; }
if (!j || typeof j !== 'object') {
    node.warn({ ia_nao_devolveu_json: bruto.slice(0, 300) });
    msg.intencao = 'outro';
    msg.entidades = {};
    msg.resposta = bruto && bruto.length < 400 ? bruto : 'Desculpe, não entendi. Pode repetir?';
    return [null, null, msg];
}

const validas = Object.keys(cat.intencoes).concat('outro');
msg.intencao = validas.includes(j.intencao) ? j.intencao : 'outro';
msg.confirmou = (typeof j.confirmou === 'boolean') ? j.confirmou : null;
msg.resposta = String(j.resposta || '').trim() || 'Desculpe, não entendi. Pode repetir?';

// Normaliza cada entidade para o valor canônico (ex.: "postinho" -> "unidade de saúde")
const ent = {};
const recebidas = j.entidades || {};
for (const nome of Object.keys(cat.entidades)) {
    let v = recebidas[nome];
    if (v === undefined || v === null || v === '') { ent[nome] = null; continue; }
    v = String(v).trim();
    const baixo = v.toLowerCase();
    for (const [canon, sins] of Object.entries(cat.entidades[nome].sinonimos)) {
        if (baixo === canon || sins.includes(baixo)) { v = canon; break; }
    }
    ent[nome] = v;
}
// Medicamento: troca pelo nome cadastrado quando bate (ex.: "losartana 50" -> "Losartana")
msg.remedioCadastrado = '';
if (ent.medicamento) {
    const m = (msg.dados.remedios || []).find(r => ent.medicamento.toLowerCase().includes(r.nome.toLowerCase()) || r.nome.toLowerCase().includes(ent.medicamento.toLowerCase()));
    if (m) { ent.medicamento = m.nome; msg.remedioCadastrado = m.nome; }
}
msg.entidades = ent;
node.status({ fill: 'blue', shape: 'dot', text: msg.intencao + ' ' + JSON.stringify(Object.fromEntries(Object.entries(ent).filter(([k, v]) => v))) });

const ehIdoso = msg.usuario && msg.usuario.perfil === 'idoso';
if (msg.intencao === 'confirmar_medicacao' && msg.confirmou !== false && ehIdoso) {
    // Sem remédio na fala, usa o que estava aguardando confirmação (variável de contexto)
    const rem = msg.remedioCadastrado || (msg.contexto && (msg.contexto.aguardando || msg.contexto.ultimo_medicamento)) || '';
    msg.params = { $idoso: msg.idosoId, $rem: rem };
    return [msg, null, null];
}
let alerta = null;
if (ehIdoso && (msg.intencao === 'pedir_ajuda' || msg.intencao === 'falar_familiar')) {
    const hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: env.get('FUSO') || 'America/Sao_Paulo' });
    const nome = msg.usuario.nome;
    const texto = msg.intencao === 'pedir_ajuda'
        ? '🚨 ' + nome + ' pediu ajuda pelo Acompanha às ' + hora + '.\nO que disse: "' + msg.pergunta + '"\nLigue agora. Se não conseguir falar, acione alguém por perto ou o SAMU (192).'
        : '📞 ' + nome + ' quer falar com ' + (ent.familiar || 'a família') + '.\nRecado: "' + msg.pergunta + '"';
    alerta = { idosoId: msg.idosoId, tipo: msg.intencao, alertaTexto: texto, teste: msg.teste };
}
return [null, alerta, msg];

// VARIÁVEL DE CONTEXTO por chat_id: última intenção, último remédio citado, o que aguarda confirmação e as últimas falas
// REPETIÇÃO DO LEMBRETE ("ainda não tomei"): a cada MINUTOS_REPETICAO, no máximo MAX_REPETICOES vezes; depois segue o alerta de 30 min
const MINUTOS_REPETICAO = Number(env.get('MINUTOS_REPETICAO')) || 10;
const MAX_REPETICOES = Number(env.get('MAX_REPETICOES')) || 2;
const contextos = flow.get('contextos') || {};
const c = contextos[msg.chatId] || { historico: [] };
c.ultima_intencao = msg.intencao;
