    msg.statusCode = 400; msg.headers = cab;
    msg.payload = { erro: 'Não recebi o áudio. Grave de novo.', texto: '' };
    return [null, msg];
}
msg.audio = buf;          // o nó "Monta envio (multipart)" descobre o formato (webm, ogg, mp4...) pelos primeiros bytes
msg.headers = cab;
return [msg, null];

// Devolve ao Webchat só o texto transcrito; o site envia esse texto pelo mesmo caminho do chat (POST /acompanha/mensagem)
const cab = { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' };
msg.headers = cab;
const t = String(msg.transcricao || '').trim();
if (msg.erroStt || !t) {
    msg.statusCode = msg.erroStt ? 502 : 422;
    msg.payload = { erro: msg.erroStt ? 'Não consegui transcrever agora.' : 'Não entendi o que foi dito.', texto: '' };
    return msg;
}
msg.statusCode = 200;
msg.payload = { texto: t };
return msg;
